const esc = value => String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
const asList = value => Array.isArray(value) ? value : value == null ? [] : typeof value === "string" ? [value] : typeof value === "object" ? Object.values(value).flatMap(asList) : [String(value)];
async function loadJson(path, base = fallbackRaw) { const response = await fetch(base + path, { cache: "no-cache" }); if (!response.ok) throw new Error(`${path} (${response.status})`); return response.json(); }
async function loadMany(paths, base = fallbackRaw, chunkSize = 40) { const result = []; for (let start = 0; start < paths.length; start += chunkSize) { result.push(...await Promise.all(paths.slice(start, start + chunkSize).map(path => loadJson(path, base)))); } return result; }
