$("grade").addEventListener("change", event => { state.filters.grade = event.target.value; refreshCourse(); }); $("subject").addEventListener("change", event => { state.filters.subject = event.target.value; state.filters.mappingId = ""; refreshCourse(); }); $("publisher").addEventListener("change", event => { state.filters.mappingId = event.target.value; renderCatalog(); }); $("search").addEventListener("input", event => { state.filters.query = event.target.value; renderAllContent(); });
function handleListen(event) { const button = event.target.closest("[data-listen]"); if (!button) return; const stepBox = button.closest(".activity-step"); const activity = button.closest(".activity"); const item = state.items.find(candidate => candidate.id === activity?.dataset.lesson); const step = item?.interactive?.steps[Number(stepBox?.dataset.step)]; const status = stepBox.querySelector(".audio-status"); if (!step?.audioScript || !status) return; if (!window.speechSynthesis || !window.SpeechSynthesisUtterance) { status.textContent = "此瀏覽器未提供語音播放；可展開逐字稿自讀，這不等同完成聽力辨識。"; return; } window.speechSynthesis.cancel(); const utterance = new window.SpeechSynthesisUtterance(step.audioScript); utterance.lang = step.audioLanguage || "en-US"; utterance.rate = 0.88; status.textContent = "正在播放；聽完後先用自己的短詞記錄。"; utterance.onend = () => { status.textContent = "播放結束。先依筆記選答；需要核對時再展開逐字稿。"; }; utterance.onerror = () => { status.textContent = "語音播放失敗；可展開逐字稿自讀，但不等同完成聽力辨識。"; }; try { window.speechSynthesis.speak(utterance); } catch { status.textContent = "語音播放失敗；可展開逐字稿自讀，但不等同完成聽力辨識。"; } }
function ensureChineseLabBound(event) { const lab = event.target.closest(".chinese-manipulation-lab"); if (!lab || lab.dataset.bound === "true") return; const item = state.items.find(candidate => candidate.id === lab.dataset.lesson); if (!item) return; window.ChineseManipulationLab?.bind(lab.parentElement, item); lab.dataset.bound = "true"; }
function handleEnglishLab(event) { const viewpoint=event.target.closest(".english-viewpoint-lab"); if(viewpoint){const out=viewpoint.querySelector(".english-lab-feedback"),b=event.target.closest("[data-view]");if(b)out.textContent={saw:"EVIDENCE：I saw two boxes leave the room 只支持『看見箱子移動』，不支持箱內物品或動機。",guess:"INFERENCE：I guessed they took it 是敘事者判斷；沒有直接證據時不能升格成事實。",told:"NEW EVIDENCE：借用紀錄可修正先前猜測；可靠閱讀要允許觀點被新證據更新。",hedge:"may + I did not see inside 明確標示不確定範圍，比無證據的 They stole it 更可靠。",careless:"ATTITUDE：careless 是評價詞，顯示敘事者態度，不等於可核對事件。",neutral:"REPORT：時間＋地點屬可查細節，適合中性公告／報告。",report:"REPORT：保留時間、地點、已確認行動；移除無證據心理與煽情評價。",diary:"DIARY：可寫 I felt / I feared，但要讓讀者知道這是個人經驗。",persuade:"PERSUADE：可選能促成行動的細節與結尾邀請，但不能改造核心事實。"}[b.dataset.view];return;} const story=event.target.closest(".english-story-lab"); if(story){const out=story.querySelector(".english-lab-feedback"),b=event.target.closest("[data-story]");if(b)out.textContent={predict:"遮住結局後，可預測 Mina 會尋找失主，因為她沒有直接帶走筆記本且主動詢問；預測仍須等後文驗證。",remove:"刪掉 ask librarian，『失主被聯絡並返回』的因果橋梁消失；原結局不能無理由保留。",leave:"若 Mina 直接離開，後續必須重寫；不能只換人物行動卻沿用 owner returns 的結局。",fact:"F 明示：Mina found a blue notebook；這是文本直接說的事件。",infer:"I 推論：Mina acted responsibly 可由她詢問並協助歸還推得，但要標成 inference，不冒充原句。"}[b.dataset.story];return;} const article=event.target.closest(".english-article-genre-lab"); if(article){const out=article.querySelector(".english-lab-feedback"),b=event.target.closest("[data-article]");if(b)out.textContent={diary:"Diary：保存個人經驗與感受；I felt relieved 只代表作者，不代表全校。",instructions:"Instructions：First/Next/Finally + 可執行動作，目標是讓新讀者照步驟完成任務。",news:"News/report：先交代可核對事件、時間、地點與有限數據；18 loans 必須保留 first week 等範圍。",opinion:"Opinion：claim + reason/evidence；should/could 表示方案或建議，不是已發生事實。",dialogue:"Dialogue：資訊由問答輪次推進；不能只因有問號就判定，還要看雙方是否互相回應。",everyone:"FAIL：18 loans ≠ everyone。把有限計數擴大成所有人，超出資料。",opened:"FAIL：should open 是建議；opened 是已發生事件，改寫偷換事實狀態。",feel:"FAIL：I felt worried 是個人感受；students felt worried 把單一經驗擴大成群體主張。"}[b.dataset.article];return;} const message=event.target.closest(".english-message-lab"); if(message){const out=message.querySelector(".english-lab-feedback"),b=event.target.closest("[data-message]");if(b)out.textContent={friend:"Friend：可自然簡短，例如 Hi Mia / Can you come?；核心時間與行動仍不能省。",teacher:"Teacher：Dear Ms. Wu + 清楚背景 + Could I...? + 禮貌結尾，正式來自關係與資訊，不是難字。",office:"School office：明確機構稱呼、目的、可查細節與回覆方式；避免 Hey buddy 等私人語氣。",card:"Card：空間短，保留稱呼、核心祝福／感謝／邀請與署名。",letter:"Letter：可分段補原因、細節、請求、結尾與署名。",email:"Email：subject 先定位任務；正文仍需稱呼、目的、必要細節、下一步與結尾。",deadline:"需要對方決定時，寫清楚要回覆什麼以及 by Wednesday 等期限。",attach:"FAIL：正文說 attached schedule 卻沒有附件會製造錯誤期待；附上檔案或刪除／改寫該句。"}[b.dataset.message];return;} const ann=event.target.closest(".english-announcement-lab"); if(ann){const out=ann.querySelector(".english-lab-feedback"),b=event.target.closest("[data-ann]");if(b)out.textContent={train:"Event=train to Hsinchu；Place=Platform 3；Time=10:15。目的地、月台、時間不能互換。",move:"Event=game moved；Place=the gym；Reason=field is wet。回答『現在在哪』要選 gym，不是原 field。",until:"until 6 p.m.：限制持續到 6 點；行動要在截止界線前完成。",after:"after dark：天黑後才進入禁止時段；不要換成 morning/noon。",between:"between 2 and 4 p.m.：允許區間兩端都要保留。",room:"Room 沒聽清楚 → Which room will it use? 精準補 Place，不要猜。",duration:"公告未提供 duration → How long will it last? 這是新問題；答案在取得前維持 unknown。"}[b.dataset.ann];return;} const chart=event.target.closest(".english-chart-lab"); if(chart){const out=chart.querySelector(".english-lab-feedback"),b=event.target.closest("[data-chart]");if(b)out.textContent={most:"Group B = 24，是三組最高；可寫 Group B collected the most bottles.",same:"A=18、C=18；可寫 Groups A and C collected the same number.",diff:"24−18=6；可寫 Group B collected six more bottles than Group A.",line:"20→25 上升；25→25 持平；25→35 上升；35→30 下降，所以不能寫 increased every day.",nounit:"FAIL：沒有 unit，24 可能是人、分鐘、公斤或百分比；主張不完整。",novalue:"LIMIT：只知道圖表主題，不知道哪類最高／最低，不能猜排名。",may:"may/might 適合標記尚待查證的解釋，並應補需要的新資料。",because:"CAUTION：只有圖表同時測到原因／設計足以支持因果時才可直接下 because 因果結論。",always:"FAIL：一次或有限期間資料不能擴大成 always/everyone。"}[b.dataset.chart];return;} const genre=event.target.closest(".english-genre-lab"); if(genre){const out=genre.querySelector(".english-lab-feedback"),b=event.target.closest("[data-genre-en]");if(b)out.textContent={facts:"事實護照：Lina／Friday／roof garden／lost mint label／follow wind／bench／stone。轉換文類前先固定這些核心。",rhyme:"Rhyme：可用短行、重複與尾音壓縮資訊，但 Lina、標籤、風向、長椅與石頭等核心不能被押韻犧牲。",prose:"Prose：用 before/then/because/so 等連接事件，敘述者負責交代時間、行動與結果。",play:"Play：把資訊分給角色台詞與舞台提示；提示應補動作／位置，不只是重複台詞。",story:"Story：追蹤人物→問題→嘗試／選擇→結果，讓事件變化可重建。",bad:"FAIL：『老師找到標籤』不在事實護照。這不是換文類，而是新增無證據情節，必須刪除或另標為創作改編。"}[b.dataset.genreEn];return;} const genreEn=event.target.closest(".english-genre-lab"); if(genreEn){const out=genreEn.querySelector(".english-lab-feedback"),b=event.target.closest("[data-genre-en]");if(b)out.textContent={facts:"事實護照：Friday；Lina；roof garden；mint label 掉落；請 Omar 一起找；沿風向；bench 旁找到；stone 固定新標籤。",rhyme:"Rhyme：可壓縮成短行、重複與尾音，但至少保留核心人物／問題／行動；押韻不能創造新結果。",prose:"Prose：由敘述者用 before/then/because/so 等線索把時間、行動與結果串起來。",play:"Play：角色台詞分配已知／目的，舞台提示補動作與位置；提示不應只重複台詞。",story:"Story：突出人物遇到問題→嘗試／選擇→新線索→結果的變化。",bad:"FAIL：『老師找到標籤』不在事實護照；這不是換文類，而是偷換事件。"}[b.dataset.genreEn];return;} const grammar=event.target.closest(".english-grammar-lab"); if(grammar){const out=grammar.querySelector(".english-lab-feedback"),b=event.target.closest("[data-grammar]");if(b)out.textContent={habit:"The market opens every Friday. 習慣／固定時程 → simple present。",past:"The market opened yesterday. 已完成事件 → simple past。",future:"The market will open tomorrow. 未來安排／預測 → will + base verb。",ella:"Ella plays tennis every Saturday. 第三人稱單數 + 習慣 → plays。",plural:"These apples are sweet. 複數主詞 → are。",must:"Visitors must wear badges. must 表必要／規定，後接原形 wear。",should:"Visitors should wear badges. should 把強度降為建議，後方仍是原形。",because:"The sign is hard to read because it is wet. because 後提供原因。",so:"The sign is wet, so we should print a new one. so 後推出結果／下一步。",if:"If it rains, we will move inside. if 建立條件，主句說條件成立時的安排。"}[b.dataset.grammar];return;} const vocab=event.target.closest(".english-vocab-clue-lab"); if(vocab){const out=vocab.querySelector(".english-lab-feedback"),b=event.target.closest("[data-vocab]");if(b)out.textContent={"open-door":"open + door：動作是把門打開；受詞 door 支持這個義項。","open-booth":"open + booth：在活動情境可表示開設／開始營運攤位，不是把 booth 當門打開。","light-bag":"light 修飾 bag，是形容重量輕；名詞位置與 bag 搭配排除『光』。","leave-books":"leave books at home：把書留在家；受詞 books + 地點 at home 決定意思。","plan-v":"We plan the route：plan 位於主詞後並帶受詞 route，是動詞。","plan-n":"The plan has three stops：有冠詞 the 且作主詞，是名詞。","borrow":"I borrow a ruler from Amy：物品由 Amy → I，borrow 看借入者。","lend":"I lend a ruler to Amy：物品由 I → Amy，lend 看提供者。","quiet":"quiet=安靜的形容詞；quick=快速的；quite=程度副詞。近形不能取代句法與語意證據。"}[b.dataset.vocab];return;} const daily=event.target.closest(".english-daily-communication-lab"); if(daily){const out=daily.querySelector(".english-lab-feedback"),b=event.target.closest("[data-daily]");if(b)out.textContent={friend:"好友間可直接些：Can you pass me the marker? 仍要說清楚物件與行動。",staff:"對陌生服務人員：Excuse me, could you tell me when the next bus leaves? 同時標出禮貌與資訊缺口。",price:"How much is this notebook? → 回答價格，如 It’s fifty dollars.",place:"Where can I buy a ticket? → 回答地點，如 At the ticket counter.",time:"What time does the movie start? → 回答時刻，如 At 7:30.",invite:"Are you free...? 先確認時間；Would you like...? 才提出邀請。接受後仍可追問 where/when。",sorry:"I’m sorry I broke the cup. → 先承接道歉，再給合情境的下一步；不要跳到無關話題。",thanks:"Thank you for your help. → You’re welcome. 功能必須對接 gratitude。",way:"Could you show me the way...? → 用 Go straight / turn left 等方向資訊回應。"}[b.dataset.daily];return;} const classroom=event.target.closest(".english-classroom-lab"); if(classroom){const out=classroom.querySelector(".english-lab-feedback"),b=event.target.closest("[data-classroom]");if(b)out.textContent={teacher:"Teacher → class：Put the cards here. 可作清楚直接的全班指令。",peer:"Classmate → classmate：Could you put the cards here, please? 較適合作同儕請求。",audio:"The audio cut out. Could you repeat the instruction? 先說明聽不清的原因，再要求重複。",role:"Which part should I do? 這是在修復分工缺口，不是要求重播音訊。",borrow:"May I borrow a ruler? → Sure. Here you are. 請求、允許與交付形成完整互動。",partner:"Work with a partner = 和一位同學合作；partner 是行動對象線索。",submit:"Hand in your homework = submit/give the homework to the teacher；不要把 hand 逐字誤解。"}[b.dataset.classroom];return;} const phonics=event.target.closest(".english-phonics-lab"); if(phonics){const out=phonics.querySelector(".english-lab-feedback"),b=event.target.closest("[data-phonics]");if(b)out.textContent={hot:"hot：CVC 結構提供短 o 的常見線索。",hope:"hope：final e 不另成音節，常提示前面的 o 走向長母音；規則仍有例外。",stop:"stop：st 是 blend，/s/ 與 /t/ 都聽得到。",ship:"ship：sh 是 digraph，在此共同表示 /ʃ/。",flim:"fl + i + m：先切分、合音，再用語境或可靠音源查證新詞。",sunset:"sun + set：複合字可先讀熟悉部分，再合併讀音與意思。",green:"green：ee 在此表示長 /iː/。",exception:"have / laugh：規則透明度不足時停止硬套，改查字典／可靠音檔。"}[b.dataset.phonics];return;} const rhyme=event.target.closest(".english-rhyme-lab"); if(rhyme){const out=rhyme.querySelector(".english-lab-feedback"),b=event.target.closest("[data-rhyme]");if(b)out.textContent={night:"light /laɪt/ 與 night /naɪt/：重讀尾部 /aɪt/ 相同，押韻。",late:"light /laɪt/ 與 late /leɪt/：拼字相近但核心母音不同，不押韻。",beat:"這是教室任務明示的 4 個 clap positions；不要因此推論自然英語每字都等重。",stress:"PLAY、PARK 承載動作與地點；比 we/in/the 更適合作主要強拍。",ship:"ship 的核心母音是 /ɪ/，較短且較鬆。",sheep:"sheep 的核心母音是 /iː/；和 ship 的差異要用耳朵比較，不看字母數。"}[b.dataset.rhyme];return;} const prosody=event.target.closest(".english-prosody-lab"); if(prosody){const out=prosody.querySelector(".english-lab-feedback");const f=event.target.closest("[data-focus]");if(f)out.textContent={sam:"Who borrowed it? → SAM carries the contrastive focus.",key:"What did Sam borrow? → KEY carries the new information.",days:"Correction: THURSDAY, not TUESDAY. Stress both sides of the contrast."}[f.dataset.focus];const t=event.target.closest("[data-tone]");if(t)out.textContent=t.dataset.tone==="rise"?"↗ Rising: the statement-shaped words can become confirmation/surprise seeking a response.":"↘ Falling: the utterance sounds complete or firm in a neutral reading.";return;} const lab=event.target.closest(".english-letter-lab"); if(!lab)return; const out=lab.querySelector(".english-lab-feedback"); const letter=event.target.closest("[data-letter-demo]"); if(letter){out.textContent={I:"I：大寫字母 I；手寫時要保留可辨認的高度／筆畫，並與小寫 l、數字 1 分開。",l:"l：小寫字母 l；不要只靠上下文把模糊直線猜成 I。","1":"1：數字一；若房號或數量語境仍可能和 l 混淆，應重寫字形。"}[letter.dataset.letterDemo];return;} const b=event.target.closest("[data-case-demo]"); if(b)out.textContent={sentence:"句首：第一個英文單字通常首字母大寫。",name:"姓名／專有名稱：依名稱邊界保留必要大寫。",month:"月份如 April 要大寫，不能因位於句中就改小寫。",common:"普通名詞如 school 在句中不因『重要』自動大寫。"}[b.dataset.caseDemo]; }
function handleAnswer(event) { const answerButton = event.target.closest("[data-answer]"); if (!answerButton) return; const stepBox = answerButton.closest(".activity-step"); const activity = answerButton.closest(".activity"); const item = state.items.find(candidate => candidate.id === activity?.dataset.lesson); const step = item?.interactive?.steps[Number(stepBox?.dataset.step)]; if (!step) return; const feedback = stepBox.querySelector(".feedback"); const correct = answerButton.dataset.answer === step.answer; feedback.textContent = correct ? `${step.feedback} 可進入下一步。` : (step.retryHint || "再想一次：回顧上方的融合版重點。"); for (const option of stepBox.querySelectorAll("[data-answer]")) { const selected = option === answerButton; option.setAttribute("aria-pressed", String(selected)); option.classList.toggle("correct", selected && correct); option.classList.toggle("wrong", selected && !correct); } }
